do $do$ declare v_command text; begin select command into v_command from cron.job where jobname='geo_address_drain' and active and schedule='* * * * *'; if v_command is null or position('''batch_size'', 10' in v_command)=0 then raise exception 'Unexpected geo_address_drain command; refusing to throttle'; end if; v_command := replace(v_command, '''batch_size'', 10', '''batch_size'', 5'); perform cron.schedule('geo_address_drain', '*/2 * * * *', v_command); end $do$;
